import { useEffect } from "react";
import { Note, useGroupMode, useSharedState } from "@canvasview/kit";

type Inputs = { principal: number; rate: number; years: number };
type Data = { start: Inputs };

// Writes model.inputs, the only key its role lists in writes. data.start only seeds the shared value: once
// it is set, every component reads the same numbers, and an agent changes them with set_canvas_state.
export default function LoanInputs({ data }: { data: Data }) {
  useGroupMode();
  const [stored, setInputs, { error, loaded }] = useSharedState<Inputs | null>("model.inputs", null);
  const inputs = stored ?? data.start;
  // Seed only once the canvas's state has loaded: before that, null may mean not read yet, not unset.
  useEffect(() => {
    if (loaded && stored === null) setInputs(data.start);
  }, [loaded, stored === null]);
  const field = (name: keyof Inputs, label: string, step: number) => (
    <label style={{ display: "grid", gap: 4 }}>
      {label}
      <input
        type="number"
        step={step}
        value={inputs[name]}
        onChange={(event) => {
          const value = Number(event.target.value) || 0;
          setInputs({ ...inputs, [name]: name === "years" ? Math.max(1, Math.min(40, Math.round(value))) : value });
        }}
      />
    </label>
  );
  return (
    <div style={{ display: "grid", gap: 8, padding: 12 }}>
      <Note markdown="Change the loan. The calculation and the chart follow." />
      {field("principal", "Loan amount", 1000)}
      {field("rate", "Annual rate (%)", 0.1)}
      {field("years", "Years", 1)}
      {error ? <p role="alert">Not saved: {error}</p> : null}
    </div>
  );
}

import { useEffect } from "react";
import { Metric, Note, useGroupMode, useSharedState } from "@canvasview/kit";

type Inputs = { principal: number; rate: number; years: number };
type Results = { monthly: number; totalPaid: number; totalInterest: number };

const round = (value: number) => Math.round(value * 100) / 100;

function compute({ principal, rate, years }: Inputs) {
  const months = Math.max(1, Math.min(480, Math.round(years) * 12));
  const monthlyRate = rate / 100 / 12;
  const monthly = monthlyRate === 0 ? principal / months : (principal * monthlyRate) / (1 - Math.pow(1 + monthlyRate, -months));
  const balances: number[] = [];
  let balance = principal;
  for (let month = 1; month <= months; month++) {
    balance = balance * (1 + monthlyRate) - monthly;
    if (month % 12 === 0) balances.push(Math.max(0, Math.round(balance)));
  }
  const results: Results = { monthly: round(monthly), totalPaid: round(monthly * months), totalInterest: round(monthly * months - principal) };
  return { results, balances };
}

// Reads model.inputs and writes model.results and model.balances. Every viewer computes the same numbers,
// so it runs in group mode: no one-person lock, and its writes need no control.
export default function LoanCalculation() {
  useGroupMode();
  // No defaults of its own: it computes from the shared inputs only, so it can never disagree with them.
  const [inputs] = useSharedState<Inputs | null>("model.inputs", null);
  const [results, setResults, { error, loaded }] = useSharedState<Results | null>("model.results", null);
  const [, setBalances] = useSharedState<number[]>("model.balances", []);
  const next = inputs ? compute(inputs) : null;
  const key = next ? JSON.stringify(next.results) : "";
  // Write only once the canvas's state has loaded, so stored results are compared before they are replaced.
  useEffect(() => {
    if (!loaded || !next || JSON.stringify(results) === key) return;
    setResults(next.results);
    setBalances(next.balances);
  }, [loaded, key]);
  if (!next) return <Note markdown="The numbers appear here once the inputs load." />;
  return (
    <div style={{ display: "grid", gap: 8, padding: 12 }}>
      <Metric tiles={[
        { label: "Monthly payment", value: next.results.monthly },
        { label: "Total interest", value: next.results.totalInterest },
        { label: "Total paid", value: next.results.totalPaid },
      ]} />
      {error ? <p role="alert">Not saved: {error}</p> : null}
    </div>
  );
}

import { Chart, Note, useSharedState } from "@canvasview/kit";

// Reads model.balances only, and writes nothing.
export default function BalanceChart() {
  const [balances] = useSharedState<number[]>("model.balances", []);
  if (!balances.length) return <Note markdown="The balance appears here once the calculation runs." />;
  return <Chart type="line" rows={balances.map((value, index) => ({ label: "Year " + (index + 1), value }))} xLabel="Year" yLabel="Balance left" />;
}
